# zero / negative
for a in ["0.00","-1.00"]:
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
# exceeds
try: issue_credit_note(inv(), "60.00", "x")
except BillingError as e: print("err", e.code)
# non-issued
try: issue_credit_note(inv("draft"), "10.00", "x")
except BillingError as e: print("err", e.code, e.message)
# float rejected
try: issue_credit_note(inv(), 10.0, "x")
except BillingError as e: print("err", e.code)
# approval threshold
try: issue_credit_note(inv(price="1000.00"), "600.00", "x")
except BillingError as e: print("err", e.code)
print(issue_credit_note(inv(price="1000.00"), "600.00", "x", approved_by="mgr"))
# idempotency after state change
i = inv()
r1 = issue_credit_note(i, "10.00", "x", idempotency_key="k1")
i.status = "void"
r2 = issue_credit_note(i, "10.00", "x", idempotency_key="k1")
print("idem", r1 == r2, r2)
print("audit", audit.events("credit_note_issued")[-1])
